//! What each kind of channel holds (contract 12.6) and what is refused when one is saved.
//!
//! - **Slack**: an incoming-webhook URL, pinned to `https://hooks.slack.com`. The URL is the credential, so it
//!   is the channel's sealed secret and the stored settings hold only a shortened form of it.
//! - **Email**: the recipients. It needs the deployment's SMTP settings.
//! - **Webhook**: a URL, checked against the egress policy when it is saved and again at every send. Its
//!   sealed secret is the signing key, generated by the server and shown once.

use crucible_control::{Channel, ChannelKind, Email, JsonDoc, TxError};
use crucible_egress::{EgressPolicy, Refusal};
use serde_json::{Value, json};

/// The host of every Slack incoming webhook.
pub const SLACK_HOST: &str = "hooks.slack.com";
/// The most recipients of an email channel.
pub const MAX_RECIPIENTS: usize = 20;
/// The longest name of a channel, in characters.
pub const NAME_MAX_CHARS: usize = 80;
/// The longest target URL, in bytes.
pub const URL_MAX_BYTES: usize = 2_048;

/// The target a person gives when saving a channel.
#[derive(Clone, PartialEq, Eq)]
pub enum Target {
    /// A Slack incoming-webhook URL.
    Slack {
        /// The URL.
        url: String,
    },
    /// Email recipients.
    Email {
        /// The addresses.
        to: Vec<String>,
    },
    /// A webhook URL.
    Webhook {
        /// The URL.
        url: String,
    },
}

impl std::fmt::Debug for Target {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            // The Slack URL is a credential.
            Self::Slack { .. } => f.write_str("Slack { url: .. }"),
            Self::Email { to } => f.debug_struct("Email").field("to", to).finish(),
            Self::Webhook { url } => f.debug_struct("Webhook").field("url", url).finish(),
        }
    }
}

impl Target {
    /// The kind of channel the target makes.
    pub const fn kind(&self) -> ChannelKind {
        match self {
            Self::Slack { .. } => ChannelKind::Slack,
            Self::Email { .. } => ChannelKind::Email,
            Self::Webhook { .. } => ChannelKind::Webhook,
        }
    }
}

/// Why a channel cannot be saved.
#[derive(Clone, PartialEq, Eq, Debug, thiserror::Error)]
pub enum TargetError {
    /// A member is not valid. `field` is the member to change.
    #[error("{message}")]
    Invalid {
        /// The member.
        field: &'static str,
        /// What is wrong and what is allowed.
        message: String,
    },
    /// The egress policy refuses the URL.
    #[error("{0}")]
    Refused(Refusal),
    /// The deployment has no SMTP settings.
    #[error(
        "email channels need the mail server of this deployment; set smtp.host and smtp.from (CRUCIBLE_SMTP_HOST, \
         CRUCIBLE_SMTP_FROM) and restart"
    )]
    SmtpNotConfigured,
}

fn invalid(field: &'static str, message: impl Into<String>) -> TargetError {
    TargetError::Invalid {
        field,
        message: message.into(),
    }
}

/// Checks a channel's name.
pub fn check_name(name: &str) -> Result<String, TargetError> {
    let name = name.trim();
    if name.is_empty() || name.chars().count() > NAME_MAX_CHARS || name.chars().any(char::is_control) {
        return Err(invalid("name", "a name of 1 to 80 characters is required"));
    }
    Ok(name.to_owned())
}

/// Checks a target and returns it in its stored form: URLs trimmed, addresses case-folded and distinct.
/// `smtp` says whether the deployment can send mail.
pub fn check_target(target: Target, policy: &EgressPolicy, smtp: bool) -> Result<Target, TargetError> {
    let url = |url: String| {
        let url = url.trim().to_owned();
        if url.len() > URL_MAX_BYTES {
            return Err(invalid("url", "the URL is at most 2048 bytes"));
        }
        let target = policy.check_url(&url).map_err(TargetError::Refused)?;
        Ok((url, target))
    };
    match target {
        Target::Slack { url: given } => {
            let (given, target) = url(given)?;
            if !target.https || target.host != SLACK_HOST || target.port != 443 {
                return Err(invalid(
                    "url",
                    "a Slack channel takes an incoming-webhook URL that starts with https://hooks.slack.com/; \
                     for any other receiver use a webhook channel",
                ));
            }
            Ok(Target::Slack { url: given })
        }
        Target::Webhook { url: given } => Ok(Target::Webhook { url: url(given)?.0 }),
        Target::Email { to } => {
            if !smtp {
                return Err(TargetError::SmtpNotConfigured);
            }
            let mut addresses = Vec::new();
            for address in &to {
                let email = Email::new(address.trim()).ok_or_else(|| {
                    invalid("to", format!("`{}` is not an email address", address.trim()))
                })?;
                if !addresses.contains(&email.as_str().to_owned()) {
                    addresses.push(email.as_str().to_owned());
                }
            }
            if addresses.is_empty() || addresses.len() > MAX_RECIPIENTS {
                return Err(invalid("to", "1 to 20 recipients are required"));
            }
            Ok(Target::Email { to: addresses })
        }
    }
}

/// The settings document of a checked target, and the secret it carries itself (the Slack URL).
pub fn stored(target: &Target) -> (JsonDoc, Option<String>) {
    let (value, secret) = match target {
        Target::Slack { url } => (json!({ "hint": redact_slack(url) }), Some(url.clone())),
        Target::Email { to } => (json!({ "to": to }), None),
        Target::Webhook { url } => (json!({ "url": url }), None),
    };
    (
        JsonDoc::parse(&value.to_string()).unwrap_or_else(|_| JsonDoc::empty()),
        secret,
    )
}

/// The stored settings of a channel, read back.
#[derive(Clone, PartialEq, Eq, Debug, Default)]
pub struct Settings {
    /// The URL of a webhook channel.
    pub url: Option<String>,
    /// The recipients of an email channel.
    pub to: Vec<String>,
    /// The Slack URL shortened to its host and last characters.
    pub hint: Option<String>,
}

impl Settings {
    /// The settings a channel row holds.
    pub fn of(channel: &Channel) -> Result<Self, TxError> {
        let value: Value = serde_json::from_str(&channel.config.to_text())
            .map_err(|error| TxError::Invalid(format!("channel settings: {error}")))?;
        Ok(Self {
            url: value.get("url").and_then(Value::as_str).map(str::to_owned),
            hint: value.get("hint").and_then(Value::as_str).map(str::to_owned),
            to: value
                .get("to")
                .and_then(Value::as_array)
                .map(|list| {
                    list.iter()
                        .filter_map(|item| item.as_str().map(str::to_owned))
                        .collect()
                })
                .unwrap_or_default(),
        })
    }
}

/// A Slack URL as it may be shown: the host and the last four characters.
pub fn redact_slack(url: &str) -> String {
    let tail: String = url
        .chars()
        .rev()
        .take(4)
        .collect::<Vec<_>>()
        .into_iter()
        .rev()
        .collect();
    format!("https://{SLACK_HOST}/services/...{tail}")
}

#[cfg(test)]
mod tests {
    use crucible_egress::Mode;

    use super::*;

    fn open() -> EgressPolicy {
        EgressPolicy::default()
    }

    #[test]
    fn slack_is_pinned_to_its_host() {
        let ok = check_target(
            Target::Slack {
                url: " https://hooks.slack.com/services/T0/B0/secretpart ".to_owned(),
            },
            &open(),
            false,
        )
        .unwrap();
        let (config, secret) = stored(&ok);
        assert!(!config.to_text().contains("secretpart"));
        assert_eq!(secret.as_deref(), Some("https://hooks.slack.com/services/T0/B0/secretpart"));
        assert_eq!(
            redact_slack(secret.as_deref().unwrap()),
            "https://hooks.slack.com/services/...part"
        );
        for url in [
            "http://hooks.slack.com/services/x",
            "https://hooks.slack.com.evil.test/services/x",
            "https://evil.test/hooks.slack.com",
            "https://hooks.slack.com:8443/services/x",
        ] {
            let error = check_target(Target::Slack { url: url.to_owned() }, &open(), false).unwrap_err();
            assert!(matches!(error, TargetError::Invalid { field: "url", .. }), "{url}");
        }
        assert!(!format!("{ok:?}").contains("secretpart"));
    }

    #[test]
    fn a_webhook_passes_the_egress_policy_or_says_why_not() {
        assert!(
            check_target(
                Target::Webhook { url: "http://10.0.0.8:9000/crucible".to_owned() },
                &open(),
                false
            )
            .is_ok()
        );
        let refused = check_target(
            Target::Webhook { url: "http://169.254.169.254/latest".to_owned() },
            &open(),
            false,
        )
        .unwrap_err();
        assert!(matches!(refused, TargetError::Refused(Refusal::Metadata(_))));
        let strict = EgressPolicy { mode: Mode::Strict, ..EgressPolicy::default() };
        let refused = check_target(
            Target::Webhook { url: "https://10.0.0.8/crucible".to_owned() },
            &strict,
            false,
        )
        .unwrap_err();
        assert!(refused.to_string().contains("egress.allow_cidrs"));
    }

    #[test]
    fn email_needs_smtp_and_real_addresses() {
        let to = vec![" Ada@Example.com".to_owned(), "ada@example.com".to_owned()];
        assert_eq!(
            check_target(Target::Email { to: to.clone() }, &open(), false),
            Err(TargetError::SmtpNotConfigured)
        );
        assert_eq!(
            check_target(Target::Email { to }, &open(), true),
            Ok(Target::Email { to: vec!["ada@example.com".to_owned()] })
        );
        for to in [vec![], vec!["nobody".to_owned()]] {
            assert!(check_target(Target::Email { to }, &open(), true).is_err());
        }
    }

    #[test]
    fn names_are_trimmed_and_bounded() {
        assert_eq!(check_name("  On call ").unwrap(), "On call");
        assert!(check_name(" ").is_err());
        assert!(check_name(&"x".repeat(81)).is_err());
    }
}
